      subroutine root4(ta, ua, rr, ww, n)
      use rank4
      implicit none
      integer i, j, k, n, offset, it, iu, of(4)
      double precision t, u, t2, u2, tt, uu, d(8), g(8)
      double precision ta(*), ua(*), rr(*), ww(*)
      double precision im(8, 14), imc(8, 14)
      double precision pi, o7, o14
      parameter (pi = 3.141592653589793238462643d0)
      parameter (o7  = (2.0d0 / 14.0d0))
      parameter (o14 = (1.0d0 / 14.0d0))

      call fill4

      do i = 1, n ! loop over parameter set
        t = ta(i) 
        if (t .lt. 0.0d0) cycle 
        if (t .gt. 19682.99d0) t = 19682.99d0 
        u = ua(i) 
        tt = dsqrt(t) 
        if (tt .gt. 1.0d0) tt = dlog(t) * 0.9102392266268373d0 + 1.0d0 ! log(3)+1 
        uu = dlog10(u)

        it = tt 
        tt = tt - it
        tt = 2.0d0 * tt - 1.0d0 

        iu = uu + 7 ! 0 <= iu <= 9
        if (iu < 0 .or. iu > 10) then
          print *, "current implementation assumes 1.0d-7 < U < 1.0e3"
          stop  
        else
          uu = uu - (iu - 7)
          uu = 2.0d0 * uu - 1.0d0 
