        g(4) = t2 * d(4) - g(4) + imc(4, 6)
        g(5) = t2 * d(5) - g(5) + imc(5, 6)
        g(6) = t2 * d(6) - g(6) + imc(6, 6)
        g(7) = t2 * d(7) - g(7) + imc(7, 6)
        g(8) = t2 * d(8) - g(8) + imc(8, 6)
        d(1) = t2 * g(1) - d(1) + imc(1, 5)
        d(2) = t2 * g(2) - d(2) + imc(2, 5)
        d(3) = t2 * g(3) - d(3) + imc(3, 5)
        d(4) = t2 * g(4) - d(4) + imc(4, 5)
        d(5) = t2 * g(5) - d(5) + imc(5, 5)
        d(6) = t2 * g(6) - d(6) + imc(6, 5)
        d(7) = t2 * g(7) - d(7) + imc(7, 5)
        d(8) = t2 * g(8) - d(8) + imc(8, 5)
        g(1) = t2 * d(1) - g(1) + imc(1, 4)
        g(2) = t2 * d(2) - g(2) + imc(2, 4)
        g(3) = t2 * d(3) - g(3) + imc(3, 4)
        g(4) = t2 * d(4) - g(4) + imc(4, 4)
        g(5) = t2 * d(5) - g(5) + imc(5, 4)
        g(6) = t2 * d(6) - g(6) + imc(6, 4)
        g(7) = t2 * d(7) - g(7) + imc(7, 4)
        g(8) = t2 * d(8) - g(8) + imc(8, 4)
        d(1) = t2 * g(1) - d(1) + imc(1, 3)
        d(2) = t2 * g(2) - d(2) + imc(2, 3)
        d(3) = t2 * g(3) - d(3) + imc(3, 3)
        d(4) = t2 * g(4) - d(4) + imc(4, 3)
        d(5) = t2 * g(5) - d(5) + imc(5, 3)
        d(6) = t2 * g(6) - d(6) + imc(6, 3)
        d(7) = t2 * g(7) - d(7) + imc(7, 3)
        d(8) = t2 * g(8) - d(8) + imc(8, 3)
        g(1) = t2 * d(1) - g(1) + imc(1, 2)
        g(2) = t2 * d(2) - g(2) + imc(2, 2)
        g(3) = t2 * d(3) - g(3) + imc(3, 2)
        g(4) = t2 * d(4) - g(4) + imc(4, 2)
        g(5) = t2 * d(5) - g(5) + imc(5, 2)
        g(6) = t2 * d(6) - g(6) + imc(6, 2)
        g(7) = t2 * d(7) - g(7) + imc(7, 2)
        g(8) = t2 * d(8) - g(8) + imc(8, 2)

        offset = (i - 1) * 4
        uu = 1.0d0 / dsqrt(u)
        rr(offset + 1) = tt * g(1) - d(1) + imc(1, 1) * 0.5d0
        rr(offset + 2) = tt * g(2) - d(2) + imc(2, 1) * 0.5d0
        rr(offset + 3) = tt * g(3) - d(3) + imc(3, 1) * 0.5d0
        rr(offset + 4) = tt * g(4) - d(4) + imc(4, 1) * 0.5d0
        ww(offset + 1) = (tt * g(5) - d(5) + imc(5, 1) * 0.5d0) * uu
        ww(offset + 2) = (tt * g(6) - d(6) + imc(6, 1) * 0.5d0) * uu
        ww(offset + 3) = (tt * g(7) - d(7) + imc(7, 1) * 0.5d0) * uu
        ww(offset + 4) = (tt * g(8) - d(8) + imc(8, 1) * 0.5d0) * uu
      enddo

      return
      end

